package com.vityarthi.library.service;
import com.vityarthi.library.model.*; import com.vityarthi.library.repository.*; import com.vityarthi.library.security.*; import java.math.*; import java.time.*; import java.util.*;
public class LibraryService {
 private final BookRepository books;private final UserRepository users;private final LoanRepository loans;private final ReservationRepository reservations;private final FineEngine fine;
 public LibraryService(BookRepository b,UserRepository u,LoanRepository l,ReservationRepository r,FineEngine f){books=b;users=u;loans=l;reservations=r;fine=f;}
 public List<Book> catalogue(){return books.all();}
 private void require(User a,Permission p){if(a==null||!a.hasPermission(p))throw new SecurityException("Permission denied for role "+(a==null?"UNKNOWN":a.getRole()));}
 public long addBook(User a,Book b){require(a,Permission.MANAGE_CATALOGUE);if(b.getIsbn().isBlank()||b.getTitle().isBlank()||b.getAuthor().isBlank())throw new IllegalArgumentException("Book fields are required.");return books.insert(b);}
 public Loan issue(User a,long member,long book,LocalDate date){require(a,Permission.ISSUE_BOOK);if(!(users.findById(member).orElseThrow(()->new IllegalArgumentException("Member not found.")) instanceof Member))throw new IllegalArgumentException("Only members can borrow.");Book b=books.byId(book).orElseThrow(()->new IllegalArgumentException("Book not found."));if(b.getAvailableCopies()<1)throw new IllegalArgumentException("No copy available; reserve it.");if(loans.active(member,book).isPresent())throw new IllegalArgumentException("Member already has this book.");Loan l=new Loan(0,book,member,date,date.plusDays(14),null,BigDecimal.ZERO);long id=loans.insert(l);books.availability(book,-1);return new Loan(id,book,member,date,date.plusDays(14),null,BigDecimal.ZERO);}
 public BigDecimal returnBook(User a,long member,long book,LocalDate date){require(a,Permission.RETURN_BOOK);Loan l=loans.active(member,book).orElseThrow(()->new IllegalArgumentException("No active loan found."));if(date.isBefore(l.getIssueDate()))throw new IllegalArgumentException("Return date precedes issue date.");BigDecimal f=fine.calculateFine(l.getDueDate(),date);loans.close(l.getId(),date,f);books.availability(book,1);reservations.waitingFor(book).stream().findFirst().ifPresent(r->reservations.ready(r.getId()));return f;}
 public Reservation reserve(User a,long member,long book){require(a,Permission.RESERVE_BOOK);Member m=(Member)users.findById(member).filter(x->x instanceof Member).orElseThrow(()->new IllegalArgumentException("Member not found."));Book b=books.byId(book).orElseThrow(()->new IllegalArgumentException("Book not found."));if(b.getAvailableCopies()>0)throw new IllegalArgumentException("Book is currently available.");if(reservations.waiting(book,member))throw new IllegalArgumentException("Existing waiting reservation.");Reservation r=new Reservation(0,book,member,m.getPriority(),LocalDateTime.now(),"WAITING");reservations.insert(r);return r;}
 public List<Reservation> queue(long book){PriorityQueue<Reservation> q=new PriorityQueue<>(Comparator.comparingInt(Reservation::getPriority).reversed().thenComparing(Reservation::getReservedAt).thenComparingLong(Reservation::getId));q.addAll(reservations.waitingFor(book));List<Reservation>x=new ArrayList<>();while(!q.isEmpty())x.add(q.poll());return x;}
}